import java.util.*;

class Solution {
    static <T> List<List<T>> chunk(List<T> items, int size) {
        List<List<T>> batches = new ArrayList<>();
        for (int i = 0; i < items.size(); i += size) {
            batches.add(new ArrayList<>(items.subList(i, Math.min(i + size, items.size()))));
        }
        return batches;
    }
}
